57	class KernelModeRegister {
58	public:
59	    static KernelModeRegister& GetInstance()
60	    {
61	        static KernelModeRegister instance;
62	        return instance;
63	    }
64	
65	    static std::string Demangle(const char* symbol)
66	    {
67	        if (symbol == nullptr) {
68	            throw std::runtime_error("Failed to demangle symbol: null symbol");
69	        }
70	
71	        int status = 0;
72	        std::unique_ptr<char, decltype(&std::free)> demangled(
73	            abi::__cxa_demangle(symbol, nullptr, nullptr, &status), std::free);
74	        // abi::__cxa_demangle mallocs memory for the demangled name, so we use unique_ptr to ensure it gets freed
75	
76	        if (status == 0 && demangled != nullptr) {
77	            return std::string(demangled.get());
78	        }
79	
80	        if (status == -2) {
81	            return std::string(symbol);
82	        }
83	
84	        throw std::runtime_error("Failed to demangle symbol: " + std::string(symbol));
85	    }
86	
87	    void Register(const std::string& kernelName, KernelMode kernelMode)
88	    {
89	        kernelModeMap[Demangle(kernelName.c_str())] = kernelMode;
90	    }
91	
92	    void Clear() { kernelModeMap.clear(); }
93	
94	    KernelMode GetKenelMode(const char* mangling)
95	    {
96	        std::string kernelName = Demangle(mangling);
97	        auto it = kernelModeMap.find(kernelName);
98	        if (it != kernelModeMap.end()) {
99	            return it->second;
100	        }
101	        throw std::invalid_argument("Kernel mode not found for kernel: " + kernelName);
102	    }
103	
104	private:
105	    std::unordered_map<std::string, KernelMode> kernelModeMap;
106	};
