108	inline uint64_t ByteGetBigEndian(const uint8_t field[], const int32_t size)
109	{
110	    uint64_t ret = 0UL;
111	
112	    switch (size) {
113	        case 1:
114	            ret = static_cast<uint64_t>(*field);
115	            break;
116	        case 2:
117	            ret = (static_cast<uint64_t>(field[1U])) | ((static_cast<uint64_t>(field[0U])) << 8U); // shift 8 bit
118	            break;
119	        case 3:
120	            ret = (static_cast<uint64_t>(field[2U])) | ((static_cast<uint64_t>(field[1U])) << 8U) |
121	                  ((static_cast<uint64_t>(field[0U])) << 16U);
122	            break;
123	        case 4:
124	            ret = (static_cast<uint64_t>(field[3U])) | ((static_cast<uint64_t>(field[2U])) << 8U) |
125	                  ((static_cast<uint64_t>(field[1U])) << 16U) | ((static_cast<uint64_t>(field[0U])) << 24U);
126	            break;
127	        case 5:
128	            ret = (static_cast<uint64_t>(field[4U])) | ((static_cast<uint64_t>(field[3U])) << 8U) |
129	                  ((static_cast<uint64_t>(field[2U])) << 16U) | ((static_cast<uint64_t>(field[1U])) << 24U) |
130	                  ((static_cast<uint64_t>(field[0U])) << 32U);
131	            break;
132	        case 6:
133	            ret = (static_cast<uint64_t>(field[5U])) | ((static_cast<uint64_t>(field[4U])) << 8U) |
134	                  ((static_cast<uint64_t>(field[3U])) << 16U) | ((static_cast<uint64_t>(field[2U])) << 24U) |
135	                  ((static_cast<uint64_t>(field[1U])) << 32U) | ((static_cast<uint64_t>(field[0U])) << 40U);
136	            break;
137	        case 7:
138	            ret = (static_cast<uint64_t>(field[6U])) | ((static_cast<uint64_t>(field[5U])) << 8U) |
139	                  ((static_cast<uint64_t>(field[4U])) << 16U) | ((static_cast<uint64_t>(field[3U])) << 24U) |
140	                  ((static_cast<uint64_t>(field[2U])) << 32U) | ((static_cast<uint64_t>(field[1U])) << 40U) |
141	                  ((static_cast<uint64_t>(field[0U])) << 48U);
142	            break;
143	        case 8:
144	            ret = (static_cast<uint64_t>(field[7U])) | ((static_cast<uint64_t>(field[6U])) << 8U) |
145	                  ((static_cast<uint64_t>(field[5U])) << 16U) | ((static_cast<uint64_t>(field[4U])) << 24U) |
146	                  ((static_cast<uint64_t>(field[3U])) << 32U) | ((static_cast<uint64_t>(field[2U])) << 40U) |
147	                  ((static_cast<uint64_t>(field[1U])) << 48U) | ((static_cast<uint64_t>(field[0U])) << 56U);
148	            break;
149	        default:
150	            throw std::invalid_argument("Invalid data length: size = " + std::to_string(size) + ", support 1~8 only");
151	            break;
152	    }
153	
154	    return ret;
155	}
