157	inline uint64_t ByteGetLittleEndian(const uint8_t field[], const int32_t size)
158	{
159	    uint64_t ret = 0UL;
160	
161	    switch (size) {
162	        case 1:
163	            ret = static_cast<uint64_t>(*field);
164	            break;
165	        case 2:
166	            ret = (static_cast<uint64_t>(field[0U])) | ((static_cast<uint64_t>(field[1U])) << 8U); // shift 8 bit
167	            break;
168	        case 3:
169	            ret = (static_cast<uint64_t>(field[0U])) | ((static_cast<uint64_t>(field[1U])) << 8U) |
170	                  ((static_cast<uint64_t>(field[2U])) << 16U);
171	            break;
172	        case 4:
173	            ret = (static_cast<uint64_t>(field[0U])) | ((static_cast<uint64_t>(field[1U])) << 8U) |
174	                  ((static_cast<uint64_t>(field[2U])) << 16U) | ((static_cast<uint64_t>(field[3U])) << 24U);
175	            break;
176	        case 5:
177	            ret = (static_cast<uint64_t>(field[0U])) | ((static_cast<uint64_t>(field[1U])) << 8U) |
178	                  ((static_cast<uint64_t>(field[2U])) << 16U) | ((static_cast<uint64_t>(field[3U])) << 24U) |
179	                  ((static_cast<uint64_t>(field[4U])) << 32U);
180	            break;
181	        case 6: /* Fall through.  */
182	            ret = (static_cast<uint64_t>(field[0U])) | ((static_cast<uint64_t>(field[1U])) << 8U) |
183	                  ((static_cast<uint64_t>(field[2U])) << 16U) | ((static_cast<uint64_t>(field[3U])) << 24U) |
184	                  ((static_cast<uint64_t>(field[4U])) << 32U) | ((static_cast<uint64_t>(field[5U])) << 40U);
185	            break;
186	        case 7:
187	            ret = (static_cast<uint64_t>(field[0U])) | ((static_cast<uint64_t>(field[1U])) << 8U) |
188	                  ((static_cast<uint64_t>(field[2U])) << 16U) | ((static_cast<uint64_t>(field[3U])) << 24U) |
189	                  ((static_cast<uint64_t>(field[4U])) << 32U) | ((static_cast<uint64_t>(field[5U])) << 40U) |
190	                  ((static_cast<uint64_t>(field[6U])) << 48U);
191	            break;
192	        case 8:
193	            ret = (static_cast<uint64_t>(field[0U])) | ((static_cast<uint64_t>(field[1U])) << 8U) |
194	                  ((static_cast<uint64_t>(field[2U])) << 16U) | ((static_cast<uint64_t>(field[3U])) << 24U) |
195	                  ((static_cast<uint64_t>(field[4U])) << 32U) | ((static_cast<uint64_t>(field[5U])) << 40U) |
196	                  ((static_cast<uint64_t>(field[6U])) << 48U) | ((static_cast<uint64_t>(field[7U])) << 56U);
197	            break;
198	        default:
199	            throw std::invalid_argument("Invalid data length: size = " + std::to_string(size) + ", support 1~8 only");
200	            break;
201	    }
202	
203	    return ret;
204	}
