206	thread_local static uint64_t (*GetByte)(const uint8_t[], const int32_t) = nullptr;
207	
208	inline Elf64_Ehdr ParseElfHeader(const uint8_t* const elfData, size_t dataSize)
209	{
210	    if (dataSize < sizeof(Elf64_Ehdr)) {
211	        throw std::invalid_argument(
212	            "Input data size is too small for 64-bit ELF header, get input dataSize: " + std::to_string(dataSize) +
213	            ", requires at least: " + std::to_string(sizeof(Elf64_Ehdr)));
214	    }
215	
216	    /* Determine how to read the rest of the header.  */
217	    switch (elfData[EI_DATA]) {
218	        case ELFDATANONE:
219	        case ELFDATA2LSB:
220	            GetByte = &ByteGetLittleEndian;
221	            break;
222	        case ELFDATA2MSB:
223	            GetByte = &ByteGetBigEndian;
224	            break;
225	        default:
226	            GetByte = &ByteGetLittleEndian;
227	            break;
228	    }
229	
230	    const bool is32bitElf = (elfData[EI_CLASS] != ELFCLASS64);
231	
232	    /* Read in the rest of the header.  */
233	    if (is32bitElf) {
234	        throw std::invalid_argument("Only support input elf is 64-bit format.");
235	    }
236	
237	    Elf64_Ehdr header;
238	    size_t offset = EI_NIDENT; // Skip e_ident
239	
240	    header.e_type = static_cast<uint16_t>(GetByte(elfData + offset, 2));
241	    offset += 2;
242	    header.e_machine = static_cast<uint16_t>(GetByte(elfData + offset, 2));
243	    offset += 2;
244	    header.e_version = GetByte(elfData + offset, 4);
245	    offset += 4;
246	    header.e_entry = GetByte(elfData + offset, 8);
247	    offset += 8;
248	    header.e_phoff = GetByte(elfData + offset, 8);
249	    offset += 8;
250	    header.e_shoff = GetByte(elfData + offset, 8);
251	    offset += 8;
252	    header.e_flags = static_cast<uint32_t>(GetByte(elfData + offset, 4));
253	    offset += 4;
254	    header.e_ehsize = static_cast<uint16_t>(GetByte(elfData + offset, 2));
255	    offset += 2;
256	    header.e_phentsize = static_cast<uint16_t>(GetByte(elfData + offset, 2));
257	    offset += 2;
258	    header.e_phnum = static_cast<uint16_t>(GetByte(elfData + offset, 2));
259	    offset += 2;
260	    header.e_shentsize = static_cast<uint16_t>(GetByte(elfData + offset, 2));
261	    offset += 2;
262	    header.e_shnum = static_cast<uint16_t>(GetByte(elfData + offset, 2));
263	    offset += 2;
264	    header.e_shstrndx = static_cast<uint16_t>(GetByte(elfData + offset, 2));
265	    return header;
266	};
267	
268	inline Elf64_Shdr GetSectionHeader(const uint8_t* const elfData, size_t dataSize, Elf64_Ehdr header, uint16_t index)
269	{
270	    if (index >= header.e_shnum) {
271	        throw std::invalid_argument(
272	            "Invalid section index, get index: " + std::to_string(index) +
273	            ", but section number is: " + std::to_string(header.e_shnum));
274	    }
275	    size_t shOffset = header.e_shoff + index * header.e_shentsize;
276	    if (shOffset + sizeof(Elf64_Shdr) > dataSize) {
277	        throw std::invalid_argument("Data size is to small for parse section header[" + std::to_string(index) + "]");
278	    }
279	    const uint8_t* data = elfData + shOffset;
280	    Elf64_Shdr shdr;
281	
282	    shdr.sh_name = static_cast<uint32_t>(GetByte(data, 4));
283	    data += 4;
284	    shdr.sh_type = static_cast<uint32_t>(GetByte(data, 4));
285	    data += 4;
286	    shdr.sh_flags = GetByte(data, 8);
287	    data += 8;
288	    shdr.sh_addr = GetByte(data, 8);
289	    data += 8;
290	    shdr.sh_offset = GetByte(data, 8);
291	    data += 8;
292	    shdr.sh_size = GetByte(data, 4);
293	    data += 8;
294	    shdr.sh_link = static_cast<uint32_t>(GetByte(data, 4));
295	    data += 4;
296	    shdr.sh_info = static_cast<uint32_t>(GetByte(data, 4));
297	    data += 4;
298	    shdr.sh_addralign = GetByte(data, 8);
299	    data += 8;
300	    shdr.sh_entsize = GetByte(data, 8);
301	
302	    return shdr;
303	};
304	
305	inline ElfKernelInfo GetKernelInfo(const uint8_t* const elfData, size_t dataSize, Elf64_Shdr kernelMetaSectionHead)
306	{
307	    uint64_t remainLen = kernelMetaSectionHead.sh_size;
308	    if (remainLen + kernelMetaSectionHead.sh_offset > dataSize) {
309	        throw std::invalid_argument("Data size is to small for parse kernel meta section");
310	    }
311	    const uint8_t* curData = elfData + kernelMetaSectionHead.sh_offset;
312	    ElfKernelInfo kernelInfo;
313	    while (remainLen > sizeof(ElfTlvHead)) {
314	        const ElfTlvHead* tlvHead = reinterpret_cast<const ElfTlvHead*>(curData);
315	        const uint16_t tlvType =
316	            static_cast<uint16_t>(GetByte(reinterpret_cast<const uint8_t*>(&(tlvHead->type)), sizeof(uint16_t)));
317	        const uint16_t tlvLength =
318	            static_cast<uint16_t>(GetByte(reinterpret_cast<const uint8_t*>(&(tlvHead->length)), sizeof(uint16_t)));
319	        if ((sizeof(ElfTlvHead) + tlvLength) > remainLen) {
320	            throw std::invalid_argument("Invalid TLV length in kernel meta section");
321	        }
322	
323	        if (tlvType == FUNC_META_TYPE_KERNEL_TYPE) {
324	            if (tlvLength != sizeof(uint32_t)) {
325	                throw std::invalid_argument("Invalid kernel type length in kernel meta section");
326	            }
327	            kernelInfo.kernelType = static_cast<uint32_t>(
328	                GetByte(reinterpret_cast<const uint8_t*>(curData + sizeof(ElfTlvHead)), sizeof(uint32_t)));
329	        } else if (tlvType == FUNC_META_TYPE_MIX_TASK_RATION) {
330	            if (tlvLength != sizeof(uint16_t) * 2) {
331	                throw std::invalid_argument("Invalid mix task ration length in kernel meta section");
332	            }
333	            kernelInfo.aicRation = static_cast<uint16_t>(
334	                GetByte(reinterpret_cast<const uint8_t*>(curData + sizeof(ElfTlvHead)), sizeof(uint16_t)));
335	            kernelInfo.aivRation = static_cast<uint16_t>(GetByte(
336	                reinterpret_cast<const uint8_t*>(curData + sizeof(ElfTlvHead) + sizeof(uint16_t)), sizeof(uint16_t)));
337	        }
338	        curData += sizeof(ElfTlvHead) + tlvLength;
339	        remainLen = remainLen - (sizeof(ElfTlvHead) + tlvLength);
340	    }
341	    return kernelInfo;
342	}
343	
344	inline KernelMode ToKernelMode(ElfKernelInfo kernelInfo)
345	{
346	    if (kernelInfo.kernelType == K_TYPE_INVALID) {
347	        throw std::invalid_argument("get invalid kernel type");
348	    }
349	    if (kernelInfo.kernelType == K_TYPE_MIX_AIC_MAIN) {
350	        if (kernelInfo.aicRation == 1 && kernelInfo.aivRation == 0) {
351	            return KernelMode::AIC_MODE;
352	        } else if (kernelInfo.aicRation == 1 && kernelInfo.aivRation == 1) {
353	            return KernelMode::MIX_AIC_1_1;                                  // MIX_AIC_1_1
354	        } else if (kernelInfo.aicRation == 1 && kernelInfo.aivRation == 2) { // aic num 1, aiv num 2
355	            return KernelMode::MIX_MODE;                                     // MIX_MODE
356	        }
357	    } else if (kernelInfo.kernelType == K_TYPE_AIC || kernelInfo.kernelType == K_TYPE_AIC_ROLLBACK) {
358	        return KernelMode::AIC_MODE; // => AIC_MODE
359	    } else if (
360	        kernelInfo.kernelType == K_TYPE_AIV || kernelInfo.kernelType == K_TYPE_AIV_ROLLBACK ||
361	        kernelInfo.kernelType == K_TYPE_MIX_AIV_MAIN) {
362	        return KernelMode::AIV_MODE; // AIV_MODE
363	    }
364	    return KernelMode::MIX_MODE;
365	}
366	
367	// Extract kernel name from section name by stripping .ascend.meta. prefix and _mix_aiv/_mix_aic postfix
368	// Returns empty string if sectionName is not a kernel meta section
369	inline std::string ExtractKernelName(const std::string& sectionName)
370	{
371	    if (sectionName.length() > PREFIX_LEN && sectionName.compare(0, PREFIX_LEN, KERNEL_SECTION_NAME_PREFIX) == 0) {
372	        size_t kernelNameLen = sectionName.length() - PREFIX_LEN;
373	        if (kernelNameLen > MIX_SUFFIX_LEN) {
374	            size_t suffixPos = sectionName.length() - MIX_SUFFIX_LEN;
375	            if (sectionName.compare(suffixPos, MIX_SUFFIX_LEN, KERNEL_MIX_AIV_POSTFIX) == 0 ||
376	                sectionName.compare(suffixPos, MIX_SUFFIX_LEN, KERNEL_MIX_AIC_POSTFIX) == 0) {
377	                kernelNameLen -= MIX_SUFFIX_LEN;
378	            }
379	        }
380	        return sectionName.substr(PREFIX_LEN, kernelNameLen);
381	    }
382	    return "";
383	}
384	
385	inline void ParseKernelSections(
386	    const uint8_t* const elfData, size_t dataSize, Elf64_Ehdr header, Elf64_Shdr shStrTabHdr)
387	{
388	    const uint8_t* shStrTab = elfData + shStrTabHdr.sh_offset;
389	    if (shStrTabHdr.sh_offset + shStrTabHdr.sh_size > dataSize) {
390	        throw std::invalid_argument("Data size is to small for parse section header string table");
391	    }
392	    for (int i = 0; i < header.e_shnum; ++i) {
393	        Elf64_Shdr shdr = GetSectionHeader(elfData, dataSize, header, i);
394	        std::string sectionName(reinterpret_cast<const char*>(shStrTab) + shdr.sh_name);
395	        std::string kernelName = ExtractKernelName(sectionName);
396	        if (!kernelName.empty()) {
397	            try {
398	                ElfKernelInfo kernelInfo = GetKernelInfo(elfData, dataSize, shdr);
399	                KernelMode kernelMode = ToKernelMode(kernelInfo);
400	                KernelModeRegister::GetInstance().Register(kernelName, kernelMode);
401	            } catch (std::invalid_argument& e) {
402	                throw std::invalid_argument("Failed to get kernel mode from section " + sectionName + ": " + e.what());
403	            }
404	        }
405	    }
406	}
407	
408	inline void RegisterKernelElf(const uint8_t* const elfData, size_t dataSize)
409	{
410	    Elf64_Ehdr header = ParseElfHeader(elfData, dataSize);
411	    Elf64_Shdr shStrTabHdr = GetSectionHeader(elfData, dataSize, header, header.e_shstrndx);
412	    ParseKernelSections(elfData, dataSize, header, shStrTabHdr);
413	}
414	
415	} // namespace AscendC
416	#endif // KERNEL_ELF_PARSER_H
